package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class StatementController {

    /** A person's statements as the screen shows them; the last due-total has two decimals, null when n/a. */
    public record StatementSummaryView(Long personId, int count, String lastDueTotal, LocalDate lastDate) {
        static StatementSummaryView of(StatementService.Summary summary) {
            return new StatementSummaryView(summary.personId(), summary.count(),
                    summary.lastDueTotal() == null ? null : summary.lastDueTotal().setScale(2).toPlainString(),
                    summary.lastDate());
        }
    }

    /** A statement just taken: the person's statements and their claims as they now stand. */
    public record StatementTakenView(StatementSummaryView summary, List<ClaimView> claims) {}

    private final StatementService service;

    public StatementController(StatementService service) {
        this.service = service;
    }

    @GetMapping("/statements")
    public List<StatementSummaryView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.summaries(sheetId).stream().map(StatementSummaryView::of).toList();
    }

    @PostMapping("/people/{personId}/statement")
    public StatementTakenView take(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        StatementService.Taken taken = service.take(sheetId, user, personId);
        return new StatementTakenView(StatementSummaryView.of(taken.summary()),
                taken.claims().stream().map(ClaimView::of).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A statement taken for a person on a sheet: their due-total at that moment (none when it was n/a),
 * the sheet's today when it was taken, and who took it.
 */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "statement_date", nullable = false)
    private LocalDate date;

    @Column(name = "taken_by", nullable = false, length = 100)
    private String takenBy;

    protected Statement() {}

    public Statement(String sheetId, Long personId, BigDecimal dueTotal, LocalDate date, String takenBy) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.date = date;
        this.takenBy = takenBy;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public BigDecimal getDueTotal() { return dueTotal; }

    public LocalDate getDate() { return date; }

    public String getTakenBy() { return takenBy; }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    List<Statement> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The statements taken for people on a sheet. Taking one records the person's due-total at that
 * moment (late charges included, at most the sheet's cap) and binds each of their claims that counts to the figure it has
 * then, without its late charge, which keeps following the sheet's today; their other claims
 * are left unbound, their due live again. A claim's due fixed when settled stays as it is.
 */
@Service
public class StatementService {

    /** A person's statements: how many, and the last one's due-total (null when n/a) and date. */
    public record Summary(Long personId, int count, BigDecimal lastDueTotal, LocalDate lastDate) {}

    /** A statement just taken, with the person's claims as they now stand. */
    public record Taken(Summary summary, List<Claim> claims) {}

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateService rates;
    private final SheetRepository sheets;
    private final RollupService rollup;
    private final Audit audit;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimService claimService, RateService rates, SheetRepository sheets, RollupService rollup, Audit audit) {
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, for those with any. */
    @Transactional(readOnly = true)
    public List<Summary> summaries(String sheetId) {
        Map<Long, List<Statement>> byPerson = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            byPerson.computeIfAbsent(s.getPersonId(), id -> new ArrayList<>()).add(s);
        }
        return byPerson.entrySet().stream().map(e -> summaryOf(e.getKey(), e.getValue())).toList();
    }

    @Transactional
    public Taken take(String sheetId, String user, Long personId) {
        // Lock the sheet so the claims and rates read are not changed while the statement is taken.
        Sheet sheet = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate today = sheet.getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        boolean fixed = false;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim, today)) {
                claim.unstate();
                continue;
            }
            BigDecimal figure = claimService.figureOf(sheetId, person, claim);
            BigDecimal due = claimService.chargedFigureOf(sheetId, person, claim);
            if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
            // a due under a grade they had on its date but not today counts like a fixed one
            if (due != null && !person.gradeOn(claim.getDate()).equals(person.gradeOn(today))) fixed = true;
            // and so does a due under a rate that is not the one in force today
            String grade = person.gradeOn(claim.getDate());
            if (due != null && !rates.on(sheetId, grade, claim.getDate()).map(Rate::getId)
                    .equals(rates.on(sheetId, grade, today).map(Rate::getId))) fixed = true;
            claim.state(figure);
            if (due != null) total = total.add(due);
            counted++;
        }
        // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
        // due, nor a due under another grade they had on its date or under a rate not in force today.
        BigDecimal dueTotal = sheet.capped(
                fixed || rates.on(sheetId, person.gradeOn(today), today).isPresent() ? total : null);
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, today, user.strip()));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user.strip() + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        return new Taken(summaryOf(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)),
                theirs);
    }

    private static Summary summaryOf(Long personId, List<Statement> list) {
        Statement last = list.get(list.size() - 1);
        return new Summary(personId, list.size(), last.getDueTotal(), last.getDate());
    }
}
-- A claim's figure bound by its person's last statement: stated is set on each claim that counted
-- when the statement was taken, with the due it had then (empty when it had none). The claim then
-- shows and totals that figure until the person's next statement rebinds or clears it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

-- Each statement taken for a person: their due-total at that moment (empty when it was n/a) and the
-- sheet's today when it was taken.
CREATE TABLE statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id      BIGINT       NOT NULL REFERENCES person (id),
    due_total      DECIMAL(14, 2),
    statement_date DATE         NOT NULL,
    taken_by       VARCHAR(100) NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
